import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_clean = df[(df['row_kind'] == 'counted') & (df['currency'] == 'USD')].copy()
except Exception:
    df_clean = df.copy()

numeric_cols = ['interval_count', 'unit_amount', 'quantity', 'discount_pct', 'mrr']
seg_cols = ['plan', 'status', 'segment']
date_col = 'created'

# EDA
try:
    eda = {}
    for col in numeric_cols:
        s = df_clean[col].dropna()
        if len(s) == 0:
            continue
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# CORRELATIONS
try:
    corr_cols = [c for c in numeric_cols if c in df_clean.columns]
    corr_matrix = df_clean[corr_cols].dropna().corr(method='pearson')
    corr_dict = {}
    for i, c1 in enumerate(corr_cols):
        for c2 in corr_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# SEGMENTATION
try:
    segs = []
    for seg in seg_cols:
        if seg not in df_clean.columns:
            continue
        for metric in numeric_cols:
            if metric not in df_clean.columns:
                continue
            grp = df_clean.groupby(seg)[metric].mean().nlargest(10)
            segs.append({
                "segment_column": seg, "metric_column": metric,
                "aggregation": "mean", "label": None,
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
    # MRR sum by segment (in_force_now)
    if 'in_force_now' in df_clean.columns:
        inf = df_clean[df_clean['in_force_now'] == 'yes']
        for seg in seg_cols:
            if seg not in inf.columns:
                continue
            grp = inf.groupby(seg)['mrr'].sum().nlargest(10)
            segs.append({
                "segment_column": seg, "metric_column": "mrr",
                "aggregation": "sum", "label": "mrr_in_force",
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
    # Churn rate by segment (cancellation_in_window)
    if 'cancellation_in_window' in df_clean.columns:
        for seg in ['plan', 'segment']:
            if seg not in df_clean.columns:
                continue
            grp = df_clean.groupby(seg).apply(
                lambda x: (x['cancellation_in_window'] == 'yes').sum() / len(x) if len(x) > 0 else 0
            )
            segs.append({
                "segment_column": seg, "metric_column": "cancellation_in_window",
                "aggregation": "ratio", "label": "cancellation_rate",
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
    result['segments'] = segs
except Exception:
    pass

# ANOMALIES
try:
    import numpy as np
    anomalies = []
    skip_cols = ['interval_count']
    check_cols = [c for c in numeric_cols if c not in skip_cols and df_clean[c].nunique() >= 5
                  and df_clean[c].isna().mean() <= 0.5]
    total_flagged = 0
    for col in check_cols:
        if total_flagged >= 25:
            break
        s = df_clean[col].dropna()
        if len(s) < 10:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo3) | (vals > hi3)
        flagged_pct = mask.sum() / len(vals)
        if flagged_pct > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{float(s.quantile(0.25)):.2f}–{float(s.quantile(0.75)):.2f}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue
        orig_q1, orig_q3 = float(s.quantile(0.25)), float(s.quantile(0.75))
        orig_iqr = orig_q3 - orig_q1
        exp_lo = orig_q1 - 3 * orig_iqr
        exp_hi = orig_q3 + 3 * orig_iqr
        flagged_idx = vals[mask].index
        for idx in flagged_idx:
            if total_flagged >= 25:
                break
            v_trans = vals.loc[idx]
            v_orig = float(df_clean.loc[idx, col])
            if v_trans > hi5 or v_trans < lo5:
                sev = "critical"
            elif v_trans > hi4 or v_trans < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": v_orig,
                "expected_range": f"{exp_lo:.2f}–{exp_hi:.2f}",
                "severity": sev,
                "explanation": f"{col} value {v_orig:.2f} lies outside expected range {exp_lo:.2f}–{exp_hi:.2f}"
            })
            total_flagged += 1
    result['anomalies'] = anomalies
except Exception:
    pass

# TRENDS (MoM on created date)
try:
    import numpy as np
    df_trend = df_clean.copy()
    df_trend[date_col] = pd.to_datetime(df_trend[date_col], errors='coerce')
    df_trend['ym'] = df_trend[date_col].dt.to_period('M')
    trends = []
    for col in ['mrr', 'unit_amount', 'discount_pct']:
        if col not in df_trend.columns:
