        pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
        direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
        trends.append({"column": col, "period": "MoM", "direction": direction,
                        "pct_change": round(pct, 2), "segment": None})
    # MRR trend by segment
    if 'segment' in df_trend.columns:
        for seg_val in df_trend['segment'].dropna().unique():
            sub = df_trend[df_trend['segment'] == seg_val]
            monthly = sub.groupby('ym')['mrr'].mean().sort_index()
            if len(monthly) < 2:
                continue
            pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": "mrr", "period": "MoM", "direction": direction,
                            "pct_change": round(pct, 2), "segment": str(seg_val)})
    result['trends'] = trends
except Exception:
    pass

# FORECASTING (simple linear extrapolation of MRR MoM)
try:
    import numpy as np
    df_fc = df_clean.copy()
    df_fc[date_col] = pd.to_datetime(df_fc[date_col], errors='coerce')
    df_fc['ym'] = df_fc[date_col].dt.to_period('M')
    monthly_mrr = df_fc.groupby('ym')['mrr'].mean().sort_index()
    if len(monthly_mrr) >= 3:
        x = np.arange(len(monthly_mrr))
        y = monthly_mrr.values
        coeffs = np.polyfit(x, y, 1)
        slope, intercept = coeffs[0], coeffs[1]
        last_period = monthly_mrr.index[-1]
        fps = []
        for i in range(1, 4):
            next_p = last_period + i
            pred = slope * (len(monthly_mrr) - 1 + i) + intercept
            fps.append({"period": str(next_p), "value": round(float(pred), 2)})
        result['forecast_points'] = fps
except Exception:
    pass

result['assumptions'] = [
