        s = df_clean[col].dropna()
        if len(s) < 10:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo3) | (vals > hi3)
        flagged_pct = mask.sum() / len(vals)
        if flagged_pct > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{float(s.quantile(0.25)):.2f}–{float(s.quantile(0.75)):.2f}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue
        orig_q1, orig_q3 = float(s.quantile(0.25)), float(s.quantile(0.75))
        orig_iqr = orig_q3 - orig_q1
        exp_lo = orig_q1 - 3 * orig_iqr
        exp_hi = orig_q3 + 3 * orig_iqr
        flagged_idx = vals[mask].index
        for idx in flagged_idx:
            if total_flagged >= 25:
                break
            v_trans = vals.loc[idx]
            v_orig = float(df_clean.loc[idx, col])
            if v_trans > hi5 or v_trans < lo5:
                sev = "critical"
            elif v_trans > hi4 or v_trans < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": v_orig,
                "expected_range": f"{exp_lo:.2f}–{exp_hi:.2f}",
                "severity": sev,
                "explanation": f"{col} value {v_orig:.2f} lies outside expected range {exp_lo:.2f}–{exp_hi:.2f}"
            })
            total_flagged += 1
    result['anomalies'] = anomalies
except Exception:
    pass

